insert into public.stages (id, slug, name, course_week, summary) values
  (1, 'empathize', 'Empathize', 1, 'Understand people in the context of the design challenge: observe, engage, immerse.'),
  (2, 'define',    'Define',    2, 'Synthesize findings into a meaningful, actionable problem statement (Point of View).'),
  (3, 'ideate',    'Ideate',    3, 'Generate a wide range of ideas; go for volume and defer judgment.'),
  (4, 'prototype', 'Prototype', 3, 'Build low-resolution artifacts that let users experience and react to an idea.'),
  (5, 'test',      'Test',      4, 'Put prototypes in front of users to learn and refine both the solution and the POV.')
insert into public.questions (stage_id, lesson_id, kind, prompt, choices, answer, explanation, clo_code) values
  (1, null, 'mcq', 'What is the goal of the Empathize stage?', '["To choose the final solution","To understand the people you are designing for and the context of their problem","To build a working prototype","To write the project report"]'::jsonb, '1', 'Empathize is about understanding users'' experiences, motivations and needs before any problem is defined.', '1A-I'),
  (1, null, 'mcq', 'Which three modes of empathizing does the d.school Design Thinking Bootleg describe?', '["Plan, build, launch","Read, write, present","Observe, engage, immerse","Ask, answer, vote"]'::jsonb, '2', 'Observe people in context, engage them in conversation, and immerse yourself in their experience.', '1A-I'),
  (1, null, 'mcq', 'Which activity is an example of ''Engage''?', '["Watching students in the library without talking to them","Revising for a week exactly the way students do","Reading statistics about exam results","Interviewing a student about how they revise for exams"]'::jsonb, '3', 'Engage means interacting with users, for example through interviews. Watching is Observe and doing it yourself is Immerse.', '1A-I'),
  (1, null, 'mcq', 'Which activity is an example of ''Immerse''?', '["Taking the same bus route to campus every day to experience a commuter''s trip","Sending an online survey to commuters","Brainstorming 50 ideas for better buses","Building a cardboard model of a bus stop"]'::jsonb, '0', 'Immerse means experiencing what the user experiences first-hand.', '1A-I'),
  (1, null, 'mcq', 'Which activity is an example of ''Observe''?', '["Asking students to rate the canteen from 1 to 5","Watching how students queue at the canteen without interrupting them","Eating at the canteen every day for a week","Writing a problem statement about the canteen"]'::jsonb, '1', 'Observe means watching people in their real context, without steering what they do.', '1A-I'),
  (1, null, 'mcq', 'A student says ''I love group work'' but never turns up to meetings. Which two empathy map quadrants conflict?', '["Think and Feel","Think and Do","Say and Do","Say and Feel"]'::jsonb, '2', 'What people say and what they do often differ. The gap points to a hidden need worth exploring.', '1A-I'),
  (1, null, 'mcq', 'In an empathy map, which quadrants are usually inferred rather than directly observed?', '["Say and Do","Say and Think","Do and Feel","Think and Feel"]'::jsonb, '3', 'Say and Do come from observation and interviews. Think and Feel are interpretations, so treat them as assumptions to check.', '1A-I'),
  (1, null, 'mcq', 'Why is it useful to keep asking ''why'' during an interview?', '["To move from surface answers to the underlying motivations and needs","To make the interviewee agree with you","To fill time until the interview ends","To test whether the prototype works"]'::jsonb, '0', 'Repeated ''why'' questions uncover the reasons behind behavior, which is where needs and insights live.', '1A-I'),
  (1, null, 'mcq', 'Which interview question is best for empathizing?', '["Don''t you think a study app would help you?","Can you tell me about the last time you studied for an exam?","Would you pay for a study app?","Which of these three app designs do you prefer?"]'::jsonb, '1', 'Open, story-based questions about real past experience give richer information than opinions about a solution.', '1A-I'),
  (1, null, 'mcq', 'Which of these is a leading question that you should avoid?', '["How do you usually feel about group work?","What happened the last time you worked in a group?","Wouldn''t you agree that group work is stressful?","Can you describe a group project you remember well?"]'::jsonb, '2', 'A leading question suggests the answer you expect, so the user echoes your assumption instead of telling you theirs.', '1A-I'),
  (1, null, 'mcq', 'Why does the Bootleg suggest talking to ''extreme'' users?', '["They represent the average user exactly","They are the quickest to recruit","They always give positive feedback","Their strong needs and workarounds make needs easier to see"]'::jsonb, '3', 'Extreme users exaggerate behaviors and needs that everyone has to a lesser degree, which makes them easier to spot.', '1A-I'),
  (1, null, 'mcq', 'A team finds that students say they want more study time but spend free hours on their phones. This is best described as:', '["A contradiction between saying and doing that can reveal a hidden need","A sign the interviews were invalid","A reason to ignore the interview data","The final problem statement"]'::jsonb, '0', 'Contradictions are valuable clues. Explore why the gap exists instead of discarding the data.', '1A-I'),
  (1, null, 'mcq', 'What is the main goal of teamwork in INT100?', '["To split the report so each member does one stage alone","To work together toward a shared goal, with a work plan and tracked artifacts","To let the strongest member do the project","To avoid giving each other feedback"]'::jsonb, '1', 'The course outcome 3C-I is to create a work plan and track work artifacts as a team.', '3C-I'),
  (1, null, 'mcq', 'In INT100, what is the team''s GitHub repository used for?', '["Hosting the midterm exam","Chatting with the lecturer","Submitting and tracking each stage''s work artifacts and revisions","Selling the prototype"]'::jsonb, '2', 'The repository shows each stage''s work, how it was revised after feedback, and who contributed.', '3C-I'),
  (1, null, 'true_false', 'Empathize means asking users what solution they want.', null, 'false', 'Empathize is about understanding needs and context. Users often cannot name the right solution, and asking for one skips the learning.', '1A-I'),
  (1, null, 'true_false', 'Observing users in their real context can reveal needs they cannot put into words.', null, 'true', 'People often do things they don''t notice or can''t explain. Observation captures what interviews miss.', '1A-I'),
  (1, null, 'true_false', 'An empathy map should only contain facts you directly observed.', null, 'false', 'Think and Feel are inferred. Include them, but label them as assumptions to verify.', '1A-I'),
  (1, null, 'true_false', 'A good interview mostly consists of the interviewer explaining their own idea.', null, 'false', 'In an empathy interview the user should do most of the talking. Pitching your idea biases their answers.', '1A-I'),
  (1, null, 'true_false', 'Silence during an interview can be useful because it gives the person room to continue.', null, 'true', 'Pausing instead of filling the gap often leads people to add the more honest or detailed part of their answer.', '1A-I'),
  (1, null, 'true_false', 'The Empathize stage happens once at the start and is never revisited.', null, 'false', 'Design thinking is iterative. Later stages often send teams back to learn more about users.', '1A-I'),
  (1, null, 'true_false', 'Recording quotes in the user''s own words helps the team avoid adding its own assumptions.', null, 'true', 'Verbatim quotes keep the evidence separate from the team''s interpretation.', '1A-I'),
  (1, null, 'true_false', 'Setting aside your own assumptions is an important part of empathizing.', null, 'true', 'Empathy requires suspending judgment so you can see the situation as the user does.', '1A-I'),
  (1, null, 'true_false', 'A team member who commits to the GitHub repository only once, at the end, still shows good progression.', null, 'false', 'The rubric rewards clear, regular revisions that show progression from stage to stage.', '3C-I'),
  (1, null, 'true_false', 'In INT100 teams, roles such as facilitator, recorder and presenter rotate across stages.', null, 'true', 'Rotating roles spread responsibility, and each member''s role fulfillment is part of the participation score.', '3C-I'),
  (1, null, 'short_answer', 'Explain the difference between Observe, Engage and Immerse, and give one example of each.', null, 'Observe: watch people in context without interfering, e.g. watch how students queue at the canteen. Engage: talk with them, e.g. interview a student about their last exam revision. Immerse: experience it yourself, e.g. take the same bus route as a commuter for a week.', 'A good answer defines all three modes and gives a realistic example for each.', '1A-I'),
  (1, null, 'short_answer', 'A student says they study best at night but they sleep through the morning class. Give one item for each of Say, Do, Think and Feel.', null, 'Say: ''I focus better at night.'' Do: sleeps through the 8:30 class. Think: ''I can catch up from the slides later.'' Feel: guilty and anxious about falling behind.', 'Say and Do are observable; Think and Feel are inferences, so any reasonable inference is fine.', '1A-I'),
  (1, null, 'short_answer', 'Rewrite this as an open, non-leading interview question: ''Don''t you find the library too noisy?''', null, 'Tell me about the last time you studied in the library. What was it like?', 'A good rewrite is open, asks about a real experience, and does not suggest an answer.', '1A-I'),
  (1, null, 'short_answer', 'Why does Empathize come before Define? Answer in two or three sentences.', null, 'Define needs real insights about users. Without understanding people first, the team would write a problem statement from its own assumptions and risk solving the wrong problem.', 'Mention that Define depends on what you learned from users.', '1A-I'),
  (1, null, 'short_answer', 'How would your team organize its GitHub repository so progression across the five stages is clear?', null, 'One section or folder per stage with its artifacts (empathy map, POV, ideas, prototype photos, test notes) and a retrospective. Frequent commits with clear messages, and revisions committed after feedback.', 'Look for per-stage structure, regular commits and visible revisions.', '3C-I'),
  (1, null, 'short_answer', 'Name two things you can do to avoid bias during an interview.', null, 'Ask open, non-leading questions; listen more than you talk; record quotes verbatim; ask ''why''; set aside assumptions; interview more than one person.', 'Any two sound practices are fine.', '1A-I'),
  (2, null, 'mcq', 'What is the goal of the Define stage?', '["To brainstorm as many ideas as possible","To test a prototype with users","To synthesize what you learned into a clear, actionable problem statement","To collect more interview data"]'::jsonb, '2', 'Define turns research into a focused problem the team can ideate on.', '1A-I'),
  (2, null, 'mcq', 'In ''Maya, a first-year student, needs to feel safe asking for help because she fears looking behind'', which part is the insight?', '["Maya, a first-year student","needs to feel safe asking for help","The whole sentence is the user","because she fears looking behind"]'::jsonb, '3', 'User + need + insight: the insight explains why the need exists.', '1A-I'),
  (2, null, 'mcq', 'What is the best way to phrase a need in a POV statement?', '["As a verb describing what the user is trying to do or feel","As a feature the user wants","As a technology to use","As a number to improve"]'::jsonb, '0', 'Needs are verbs (''to feel in control''), not nouns (''an app''). Nouns smuggle in a solution.', '1A-I'),
  (2, null, 'mcq', 'Which of these is a solution disguised as a need?', '["Students need to feel in control of overlapping deadlines","Students need a mobile app to track deadlines","Students need to trust that nothing important will slip through","Students need to understand what is expected of them each week"]'::jsonb, '1', '''A mobile app'' is a solution. The other options describe what the user is trying to achieve or feel.', '1A-I'),
  (2, null, 'mcq', 'In a POV statement, what does the insight explain?', '["Which technology to use","How much the solution will cost","Why the need matters, based on something you learned about the user","Who will pay for it"]'::jsonb, '2', 'The insight is the surprising ''because'' that makes the need meaningful.', '1A-I'),
  (2, null, 'mcq', 'What does HMW stand for?', '["How Many Ways","How Must We","Human Measurement Works","How Might We"]'::jsonb, '3', 'HMW questions turn a POV into open prompts for ideation.', '1C-I'),
  (2, null, 'mcq', 'Why does the HMW format use the word ''might''?', '["It treats ideas as possibilities and encourages exploration without pressure","It shows the team is unsure the problem exists","It limits the team to one answer","It makes the question shorter"]'::jsonb, '0', '''Might'' lets ideas be tried and discarded without commitment.', '1C-I'),
  (2, null, 'mcq', 'Which HMW question has the best scope for the need ''feel in control of overlapping deadlines''?', '["How might we build a deadline app with push notifications?","How might we help first-year students feel in control of overlapping deadlines?","How might we fix education?","How might we remove all deadlines?"]'::jsonb, '1', 'It is focused on the user and need, but leaves room for many solutions.', '1C-I'),
  (2, null, 'mcq', 'What is the problem with an HMW question that is too broad?', '["It is too cheap to answer","It forces a single solution","The team has no clear direction for where to start ideating","It stops users from giving feedback"]'::jsonb, '2', 'Too broad a question produces unfocused ideas.', '1C-I'),
  (2, null, 'mcq', 'What is the problem with an HMW question that is too narrow?', '["It is impossible to ideate on","It requires too many users","It ignores the POV","It builds in a solution and limits creative ideas"]'::jsonb, '3', 'An overly narrow question has the answer baked in, so no new ideas appear.', '1C-I'),
  (2, null, 'mcq', 'What does it mean to ''synthesize'' research in the Define stage?', '["Group and interpret observations to find patterns and insights","Copy interview notes into the report","Delete data that seems unusual","Choose the most popular idea"]'::jsonb, '0', 'Synthesis turns raw observations into meaning.', '1A-I'),
  (2, null, 'mcq', 'Why should a problem statement be human-centered?', '["It makes the report longer","It frames the problem around a real user''s needs rather than the technology or the business","It removes the need for prototypes","It guarantees a profitable product"]'::jsonb, '1', 'A human-centered statement keeps the team focused on what matters to the user.', '1A-I'),
  (2, null, 'mcq', 'Which of these is an insight rather than just an observation?', '["Students skip some group meetings","Five of eight interviewees work part-time","Students skip group meetings because they fear being seen as the weakest member","Group meetings are held on Fridays"]'::jsonb, '2', 'An insight explains the ''why'' behind behavior. The others only state facts.', '1A-I'),
  (2, null, 'mcq', 'What makes a POV statement actionable?', '["It lists the exact features to build","It is vague enough to fit any project","It describes the team''s schedule","It gives the team a clear focus and inspires ideas to solve it"]'::jsonb, '3', 'A good POV is specific enough to guide ideation without dictating the solution.', '1C-I'),
  (2, null, 'true_false', 'A POV statement should name the solution the team plans to build.', null, 'false', 'A POV states user, need and insight. Naming the solution too early limits ideation.', '1A-I'),
  (2, null, 'true_false', 'Define turns what you learned in Empathize into a focused problem you can ideate on.', null, 'true', 'That is the purpose of the stage: from research to a clear problem to solve.', '1A-I'),
  (2, null, 'true_false', 'The same research can lead to several different POV statements.', null, 'true', 'Different users, needs and insights can be drawn from the same data. Teams choose the most promising one.', '1A-I'),
  (2, null, 'true_false', 'Insights should come from the team''s assumptions rather than user research.', null, 'false', 'Insights must be grounded in what the team learned from real users.', '1A-I'),
  (2, null, 'true_false', 'A good HMW question has one obvious answer.', null, 'false', 'HMW questions should be open enough to inspire many different ideas.', '1C-I'),
  (2, null, 'true_false', 'Writing several HMW questions for one POV is good practice.', null, 'true', 'Several questions at different scopes help the team find a productive angle for ideating.', '1C-I'),
  (2, null, 'true_false', 'The user in a POV should be as general as possible, such as ''everyone''.', null, 'false', 'A specific user makes the need and insight concrete. ''Everyone'' makes the statement vague.', '1A-I'),
  (2, null, 'true_false', 'Getting feedback on your POV from other teams helps check whether the problem is framed meaningfully.', null, 'true', 'The course schedules feedback on the Define (POV) practice for exactly this reason.', '1A-I'),
  (2, null, 'true_false', 'Defining the problem should happen before any user research.', null, 'false', 'Define comes after Empathize, so that the problem is built on user insight.', '1A-I'),
  (2, null, 'true_false', 'A need such as ''to feel in control'' is better than ''a planner app'' because it is not a solution.', null, 'true', 'Verb-based needs keep the solution space open.', '1A-I'),
  (2, null, 'short_answer', 'Write a POV statement (user + need + insight) for a first-year student who skips lab sessions to study alone.', null, 'A first-year IT student needs to feel confident she can keep up without being judged, because she believes asking questions in lab shows she is behind.', 'Check that it names a specific user, a verb-based need, and a ''because'' insight, and no solution.', '1A-I'),
  (2, null, 'short_answer', 'Write two HMW questions for the need ''to feel safe asking for help''.', null, 'How might we make asking a question in lab feel low-risk? How might we let students signal confusion without being singled out?', 'Questions should start with ''How might we'', stay open, and not name a solution.', '1C-I'),
  (2, null, 'short_answer', 'Explain why ''Students need a better app'' is a weak need statement.', null, 'It is a solution, not a need. It is vague and does not say what the user is trying to do or feel.', 'Mention that it names a solution and lacks a specific user need.', '1A-I'),
  (2, null, 'short_answer', 'What is the difference between an observation and an insight? Give an example of each.', null, 'An observation is what you saw or heard (''students skip group meetings''). An insight explains why (''they fear being seen as the weakest member'').', 'A good answer shows that an insight adds the underlying reason.', '1A-I'),
  (2, null, 'short_answer', 'Describe how you would move from a wall of interview notes to a POV statement.', null, 'Group related notes, look for patterns and contradictions, choose one user and need, write the insight that explains why, draft the POV, and check it with others.', 'Look for grouping, finding patterns, drafting, and feedback.', '1A-I'),
  (2, null, 'short_answer', 'Why should you share your POV with other teams and ask for feedback before ideating?', null, 'To check that the framing is clear, specific and meaningful, spot hidden assumptions, and avoid spending ideation time on the wrong problem.', 'Mention checking the framing before investing in ideas.', '1A-I'),
  (3, null, 'mcq', 'What is the purpose of the Ideate stage?', '["To pick the final solution immediately","To validate a solution with users","To write the project report","To generate a wide range of possible solutions to the HMW question"]'::jsonb, '3', 'Ideate is where the team deliberately explores many options.', '1C-I'),
  (3, null, 'mcq', 'In brainstorming, what does ''defer judgment'' mean?', '["Do not criticize ideas while they are being generated","Wait a day before sharing ideas","Let the lecturer judge the ideas","Only share ideas you are sure about"]'::jsonb, '0', 'Judging too early shuts down ideas. Evaluation happens afterwards.', '1C-I'),
  (3, null, 'mcq', 'Which of these is a standard brainstorming rule?', '["Judge ideas as they appear","Be visual","Only one person may contribute","Pick a favorite before starting"]'::jsonb, '1', 'Sketching and visual notes help ideas spread and combine. The others are the opposite of good practice.', '1C-I'),
  (3, null, 'mcq', 'Why encourage wild ideas?', '["They are usually the easiest to build","They reduce the number of ideas","They push the group beyond obvious solutions and can be tamed into feasible ones later","They remove the need for prototypes"]'::jsonb, '2', 'A wild idea often contains a seed of something new that can be made practical.', '1C-I'),
  (3, null, 'mcq', 'What is divergent thinking?', '["Narrowing down to one option","Testing options with users","Documenting the final decision","Generating many varied options"]'::jsonb, '3', 'Ideate starts by diverging, then converges on the best options.', '1C-I'),
  (3, null, 'mcq', 'What is convergent thinking?', '["Evaluating and selecting among the options","Generating as many ideas as possible","Interviewing more users","Writing the retrospective"]'::jsonb, '0', 'After diverging, the team converges by choosing ideas to prototype.', '1C-I'),
  (3, null, 'mcq', 'Which brainstorming rule helps everyone follow the discussion?', '["Go for quantity","One conversation at a time","Encourage wild ideas","Defer judgment"]'::jsonb, '1', 'Side conversations split attention and lose ideas.', '1C-I'),
  (3, null, 'mcq', 'What is the best way to build on a teammate''s idea?', '["Say ''but...'' and list the problems","Ignore it and share your own","Say ''yes, and...'' and extend it","Rank it against the others"]'::jsonb, '2', '''Yes, and'' keeps ideas growing; ''but'' kills them.', '1C-I'),
  (3, null, 'mcq', 'Why is quantity valued over quality in the first brainstorm?', '["The lecturer counts the ideas","Quality does not matter in design thinking","Fewer ideas are harder to prototype","More ideas increase the chance of finding a novel, strong one"]'::jsonb, '3', 'The first ideas are usually obvious. Strong ideas tend to appear after many.', '1C-I'),
  (3, null, 'mcq', 'Which method asks people to write ideas silently before sharing them?', '["Brainwriting","Interviewing","Journey mapping","Usability testing"]'::jsonb, '0', 'Brainwriting lets everyone contribute without being influenced by the loudest voice.', '1C-I'),
  (3, null, 'mcq', 'After many ideas are on the wall, each member puts dots on their favorites. What is this called?', '["Empathy mapping","Dot voting","Role-playing","A/B testing"]'::jsonb, '1', 'Dot voting is a quick way to converge on the ideas the group finds most promising.', '1C-I'),
  (3, null, 'mcq', 'Which set of criteria can a team use to choose ideas to prototype?', '["Most complex, most expensive, most colorful","Whichever the loudest member prefers","Desirable to users, feasible to build, and viable to sustain","Whichever needs no prototype"]'::jsonb, '2', 'Desirability, feasibility and viability are common criteria for choosing ideas.', '1C-I'),
  (3, null, 'mcq', 'What is the ''I like, I wish, What if'' format used for?', '["Ranking ideas by cost","Recording interview quotes","Scoring peer contribution","Giving constructive feedback that keeps ideas alive"]'::jsonb, '3', 'The format praises what works, raises concerns as wishes, and proposes new directions.', '1C-I'),
  (3, null, 'mcq', 'What is a good outcome of an Ideate session?', '["A large, varied set of ideas linked to the HMW question, with a few chosen to prototype","A single polished design","A user test report","A final presentation slide deck"]'::jsonb, '0', 'The output is options and a short list, not a finished product.', '1C-I'),
  (3, null, 'true_false', 'Criticizing an idea immediately helps the team find the best one faster.', null, 'false', 'Early criticism reduces the number and boldness of ideas.', '1C-I'),
  (3, null, 'true_false', 'The Ideate stage should produce only one idea.', null, 'false', 'Ideate aims for many ideas first. Selection comes afterwards.', '1C-I'),
  (3, null, 'true_false', 'Sketching and visual notes are encouraged during ideation.', null, 'true', '''Be visual'' is one of the standard brainstorming rules.', '1C-I'),
  (3, null, 'true_false', 'Ideate comes after Define because ideas should answer a defined problem.', null, 'true', 'The POV and HMW questions give ideation a focus.', '1C-I'),
  (3, null, 'true_false', 'Wild ideas should be rejected because they cannot be built.', null, 'false', 'Wild ideas widen the space of options and can be adapted into feasible ones.', '1C-I'),
  (3, null, 'true_false', 'Selecting ideas to prototype is part of the convergent phase of Ideate.', null, 'true', 'After generating, the team narrows down to a few ideas to build.', '1C-I'),
  (3, null, 'true_false', 'When giving feedback, you should focus on the person who proposed the idea.', null, 'false', 'Feedback should be about the idea, using constructive formats such as I like, I wish, What if.', '1C-I'),
  (3, null, 'true_false', 'All team members should contribute ideas, not just the facilitator.', null, 'true', 'Different perspectives lead to a wider range of ideas.', '3C-I'),
  (3, null, 'true_false', 'A team should stop brainstorming as soon as it has the first workable idea.', null, 'false', 'The first workable idea is rarely the best. Keep going to explore alternatives.', '1C-I'),
  (3, null, 'true_false', 'HMW questions are written after ideation, not before.', null, 'false', 'HMW questions come from Define and give Ideate its starting prompts.', '1C-I'),
  (3, null, 'short_answer', 'List three brainstorming rules and explain why one of them matters.', null, 'Defer judgment, go for quantity, encourage wild ideas, build on others'' ideas, stay on topic, be visual, one conversation at a time. Example: deferring judgment matters because early criticism makes people stop sharing.', 'Any three valid rules and a reasoned explanation for one.', '1C-I'),
  (3, null, 'short_answer', 'Write five different ideas for: ''How might we help first-year students keep track of overlapping deadlines?'' Include one wild idea.', null, 'Example: a shared class calendar; a weekly deadline summary message; a wall chart in the dorm; a buddy system that reminds each other; wild: a robot that follows you and beeps on deadline day.', 'Ideas should be varied, answer the HMW, and include at least one bold one.', '1C-I'),
  (3, null, 'short_answer', 'Explain the difference between divergent and convergent thinking in Ideate.', null, 'Divergent thinking generates many varied ideas without judging. Convergent thinking then evaluates them against criteria and selects a few to prototype.', 'Both modes should be defined and placed in order.', '1C-I'),
  (3, null, 'short_answer', 'Give feedback on this idea using I like / I wish / What if: ''A chatbot that reminds students of deadlines.''', null, 'I like that it meets students in an app they already use. I wish it let each student choose how often it reminds them. What if it grouped deadlines by course?', 'A good answer uses all three parts and stays constructive.', '1C-I'),
  (3, null, 'short_answer', 'Describe how your team would choose which ideas to prototype. Name the method and your criteria.', null, 'Use dot voting after grouping similar ideas, judging each against desirability for users, feasibility to build in the time available, and viability. Then discuss the top ideas and pick one or two.', 'Look for a method (e.g. dot voting) and sensible criteria.', '1C-I'),
  (3, null, 'short_answer', 'Why is it a mistake to use only the first idea the team thinks of?', null, 'The first idea is often the obvious one. Exploring more options can reveal better, more original solutions and shows why the chosen one is the best.', 'Mention obviousness and the value of exploring alternatives.', '1C-I'),
  (4, null, 'mcq', 'What is a prototype in design thinking?', '["A rough, tangible version of an idea built to learn from","The final product ready for launch","A written specification","A marketing poster"]'::jsonb, '0', 'Prototypes make ideas concrete enough for people to react to.', '5UX-I'),
  (4, null, 'mcq', 'Why should early prototypes be rough and cheap?', '["Users prefer ugly designs","They are quick to change, and the team does not become too attached to one idea","Polish is forbidden in design thinking","Rough prototypes need no testing"]'::jsonb, '1', 'Low investment keeps the team free to change direction.', '5UX-I'),
  (4, null, 'mcq', 'What does ''build to think'' mean?', '["Think about everything before you build anything","Build only after the lecturer approves","Making something tangible helps you work out and learn about your ideas","Build the final product first"]'::jsonb, '2', 'Building surfaces questions and problems that discussion alone does not.', '5UX-I'),
  (4, null, 'mcq', 'Which of these is a low-fidelity prototype?', '["A fully coded app on the app store","A production website with real data","A manufactured batch of products","A paper sketch of app screens"]'::jsonb, '3', 'Low fidelity means quick, rough and far from the final product.', '5UX-I'),
  (4, null, 'mcq', 'Which prototype is best for testing a service experience such as queuing at a counter?', '["Role-playing with simple props","A written essay","A database schema","A source-code review"]'::jsonb, '0', 'Service experiences are tested by acting them out.', '5UX-I'),
  (4, null, 'mcq', 'A storyboard prototype shows:', '["The server architecture","A sequence of scenes of a user''s experience with the idea","The exact code","The cost breakdown"]'::jsonb, '1', 'Storyboards communicate how an idea fits into a user''s situation over time.', '5UX-I'),
  (4, null, 'mcq', 'Each prototype should aim to answer:', '["Every question about the product at once","No question, it only needs to look good","A specific question or test a specific assumption","Only questions from the lecturer"]'::jsonb, '2', 'Knowing what you want to learn keeps the prototype small and the feedback useful.', '5UX-I'),
  (4, null, 'mcq', 'What is the benefit of building several quick prototypes instead of one detailed one?', '["It lets the team skip user testing","It reduces the need for ideas","It guarantees success","The team learns about multiple directions before investing heavily"]'::jsonb, '3', 'Exploring several options early reduces the risk of polishing the wrong one.', '5UX-I'),
  (4, null, 'mcq', 'What is a wireframe?', '["A simple layout sketch of an interface showing structure but not visual style","A finished design with animations","A data table","A usage report"]'::jsonb, '0', 'Wireframes focus on what goes where, not how it looks.', '5UX-I'),
  (4, null, 'mcq', 'What does ''fidelity'' describe in prototyping?', '["How loyal users are","How closely the prototype resembles the final product","How many people tested it","How much it costs to ship"]'::jsonb, '1', 'Low-fidelity prototypes are rough; high-fidelity ones look and feel real.', '5UX-I'),
  (4, null, 'mcq', 'Prototyping can help a team in all of these ways EXCEPT:', '["Learning what works and what doesn''t","Resolving disagreements by showing instead of telling","Removing the need to ask users for feedback","Starting conversations with users"]'::jsonb, '2', 'Prototypes exist to get feedback. They never replace it.', '5UX-I'),
  (4, null, 'mcq', 'When building a prototype, which person should the team keep in mind?', '["The team''s most senior member","The lecturer","A competitor''s designer","The user from the POV statement"]'::jsonb, '3', 'The prototype should serve the specific user and need defined earlier.', '5UX-I'),
  (4, null, 'mcq', 'Why should prototype building be time-boxed?', '["To avoid over-investing in one idea before learning from users","Because the lecturer needs the time","Because prototypes must be finished in one day by rule","To avoid writing documentation"]'::jsonb, '0', 'A time limit keeps the prototype small and the team focused on learning.', '5UX-I'),
  (4, null, 'mcq', 'Before showing a prototype to users, the team should decide:', '["How to defend the idea","What it wants to learn and what feedback to collect","Which user will be blamed","The final price"]'::jsonb, '1', 'Planning the learning goal makes the test sessions productive.', '5UX-I'),
  (4, null, 'true_false', 'A prototype must be a working, coded product.', null, 'false', 'Prototypes can be paper, cardboard, role-play or sketches. Code is optional.', '5UX-I'),
  (4, null, 'true_false', 'Prototypes can be made from paper, cardboard or role-play.', null, 'true', 'Any quick, cheap form that lets users react to the idea can serve as a prototype.', '5UX-I'),
  (4, null, 'true_false', 'Prototypes help teams decide between ideas by showing rather than telling.', null, 'true', 'Seeing an idea in tangible form settles many debates quickly.', '5UX-I'),
  (4, null, 'true_false', 'Building a prototype can reveal problems that were not obvious when only discussing the idea.', null, 'true', 'Making things exposes details and constraints that talk hides.', '5UX-I'),
  (4, null, 'true_false', 'A team should perfect one prototype before showing it to anyone.', null, 'false', 'Show early and often. Waiting for perfection delays learning.', '5UX-I'),
  (4, null, 'true_false', 'A storyboard can serve as a prototype for an experience.', null, 'true', 'It shows how a user would encounter and use the idea.', '5UX-I'),
  (4, null, 'true_false', 'Peer feedback from sharing sessions should be recorded and used in revisions.', null, 'true', 'The report rubric rewards recorded feedback that drives documented changes.', '1A-I'),
  (4, null, 'true_false', 'A prototype should test as many assumptions as possible at once.', null, 'false', 'Focus on one or a few questions so that you know what the feedback means.', '5UX-I'),
  (4, null, 'true_false', 'Failing early with a cheap prototype is a useful outcome.', null, 'true', 'Learning that an idea does not work, cheaply, saves effort later.', '5UX-I'),
  (4, null, 'true_false', 'Prototyping replaces the need for Define and Ideate.', null, 'false', 'Prototypes build on the defined problem and chosen ideas. They do not replace those steps.', '5UX-I'),
  (4, null, 'short_answer', 'Explain the difference between low-fidelity and high-fidelity prototypes and when each is appropriate.', null, 'Low-fidelity prototypes (paper, cardboard, role-play) are quick and cheap and suit early exploration. High-fidelity prototypes look and behave close to the real product and suit later testing of details.', 'Define both and tie each to a stage of the work.', '5UX-I'),
  (4, null, 'short_answer', 'Pick one idea from your project and describe a prototype you could build in under an hour. What question will it answer?', null, 'Example: paper screens of a deadline planner, tested to see whether students can find this week''s deadlines in 10 seconds.', 'A good answer is quick to build, specific, and linked to a clear question.', '5UX-I'),
  (4, null, 'short_answer', 'Why does the course have teams share their prototype with other teams before the final test?', null, 'To get early peer feedback, see problems the team missed, and revise before testing more formally. The feedback is recorded and used in the next revision.', 'Mention early feedback and revision.', '1A-I'),
  (4, null, 'short_answer', 'List three ways to prototype a mobile app idea without writing code.', null, 'Paper sketches of screens, clickable mockups in a design tool, a storyboard, role-playing the app with a person acting as the phone.', 'Any three valid no-code methods.', '5UX-I'),
  (4, null, 'short_answer', 'Describe what to record when peers give feedback on your prototype, and how to use it.', null, 'Record what they liked, what confused them, their questions and their ideas, with quotes. Then decide what to change, make the revision, and note the change in the repository.', 'Look for recording, deciding, revising and documenting.', '1A-I'),
  (4, null, 'short_answer', 'What does ''build to think'' mean? Give an example.', null, 'Making something tangible, such as a cardboard model, helps you discover and answer questions that talking cannot, for example realizing the buttons are too small once you hold the model.', 'Explain the idea and give a concrete example.', '5UX-I'),
  (5, null, 'mcq', 'What is the main purpose of the Test stage?', '["To prove the idea is perfect","To get feedback on prototypes to refine solutions and learn more about the user","To finalize the report","To select team roles"]'::jsonb, '1', 'Testing is about learning, not about winning approval.', '5UX-I'),
  (5, null, 'mcq', 'How should you introduce the prototype to a tester?', '["Explain every feature first","Tell them what they should like","Let them experience it without explaining too much","Use it yourself while they watch"]'::jsonb, '2', 'Show, don''t tell. Over-explaining hides the problems real users would hit.', '5UX-I'),
  (5, null, 'mcq', 'A user struggles with your prototype. The best response is to:', '["Immediately correct them","Defend the design","End the test","Stay quiet, observe, and note where and why they struggle"]'::jsonb, '3', 'Struggles are the most valuable data. Interrupting removes them.', '5UX-I'),
  (5, null, 'mcq', 'In the feedback capture grid, where do you record a tester asking ''Would this work offline?''', '["Questions","Likes","Criticisms","Ideas"]'::jsonb, '0', 'The grid has four parts: likes, criticisms, questions and ideas.', '5UX-I'),
  (5, null, 'mcq', 'Which question helps you learn why a user reacted as they did?', '["You like it, right?","Can you tell me why you tapped there?","Don''t you think this is easy to use?","Would everyone use this?"]'::jsonb, '1', 'Neutral, open questions reveal reasoning without leading.', '5UX-I'),
  (5, null, 'mcq', 'Why test with real users instead of only teammates?', '["Teammates are too busy","Users are cheaper","Teammates share your assumptions and already know how it should work","Real users never find problems"]'::jsonb, '2', 'Outsiders reveal problems that the team cannot see.', '5UX-I'),
  (5, null, 'mcq', 'What might testing lead the team to do next?', '["Stop immediately","Skip straight to launch","Delete the research","Iterate: refine the prototype or return to an earlier stage"]'::jsonb, '3', 'The process is iterative. Test results feed back into earlier stages.', '5UX-I'),
  (5, null, 'mcq', 'Which statement best describes feedback in the Test stage?', '["Feedback is data to learn from, not a judgment of the team","Feedback only counts if it is positive","Critical feedback should be ignored","Feedback is only the lecturer''s job"]'::jsonb, '0', 'Treat criticism as information that improves the solution.', '5UX-I'),
  (5, null, 'mcq', 'Which is a testable assumption?', '["Students are happy","Students will find the deadline list within 10 seconds","The app is good","Design is important"]'::jsonb, '1', 'A testable assumption is specific and observable.', '5UX-I'),
  (5, null, 'mcq', 'Why test the prototype in context when possible?', '["It is always cheaper","It makes the prototype look better","Real settings reveal factors a classroom cannot, such as noise, time pressure and distractions","It removes the need for notes"]'::jsonb, '2', 'Context shapes how people use things.', '5UX-I'),
  (5, null, 'mcq', 'What should you record during a test session?', '["Only the final satisfaction score","Only compliments","Only what supports the idea","What users do and say, including surprises and quotes"]'::jsonb, '3', 'Good notes capture behavior and words, including the unexpected.', '5UX-I'),
  (5, null, 'mcq', 'What is the purpose of retrospection in week 5?', '["To reflect on what worked, what didn''t and what to improve in how the team worked","To grade teammates in secret","To plan next semester''s course","To submit the final code"]'::jsonb, '0', 'Retrospectives help the team learn from their own process.', '3C-I'),
  (5, null, 'mcq', 'What should the retrospective for each stage in the report include?', '["Only a list of tools used","Specific reflection on successes, challenges and improvements","A copy of the lecture slides","Only the team members'' names"]'::jsonb, '1', 'The rubric asks for clear, specific reflection that shows how the team adapted.', '3C-I'),
  (5, null, 'mcq', 'Which statement about iteration is correct?', '["Once you reach Test the process is over","Testing only validates and never changes anything","Test results can send the team back to Empathize, Define, Ideate or Prototype","Iteration means repeating the exact same test"]'::jsonb, '2', 'The five stages are not a strict line. Learning at any stage can send you back.', '5UX-I'),
  (5, null, 'true_false', 'In Test, the team should defend its prototype when users criticize it.', null, 'false', 'Defending stops the learning. Listen and ask questions instead.', '5UX-I'),
  (5, null, 'true_false', 'Testing can reveal that the POV statement needs to be revised.', null, 'true', 'Test results may show that the team framed the problem or the user''s need wrongly.', '5UX-I'),
  (5, null, 'true_false', 'Testing should happen only once, after the final product is built.', null, 'false', 'Test early and often with rough prototypes, then iterate.', '5UX-I'),
  (5, null, 'true_false', 'Observing what users do is as important as hearing what they say.', null, 'true', 'People''s actions often reveal more than their words.', '5UX-I'),
  (5, null, 'true_false', 'A test should be planned so that it answers specific questions about the prototype.', null, 'true', 'A clear learning goal makes it possible to decide what to observe and record.', '5UX-I'),
  (5, null, 'true_false', 'Negative feedback means the project has failed.', null, 'false', 'Negative feedback is useful information that shows what to improve.', '5UX-I'),
  (5, null, 'true_false', 'Showing rather than telling lets users form their own reactions to the prototype.', null, 'true', 'Unprompted reactions are more honest than reactions to your explanation.', '5UX-I'),
  (5, null, 'true_false', 'Teams should record test results and the changes they make in their GitHub repository.', null, 'true', 'The repository documents progression and iteration, which is part of the rubric.', '3C-I'),
  (5, null, 'true_false', 'Peer evaluation in INT100 asks teammates to assess contribution, collaboration and reliability.', null, 'true', 'Those are the three criteria in the peer evaluation rubric.', '3C-I'),
  (5, null, 'true_false', 'Only users who already like your idea should be asked to test it.', null, 'false', 'Testers who already like the idea give biased feedback. Include people who match the real user.', '5UX-I'),
  (5, null, 'short_answer', 'Describe how you would run a 10-minute test of a paper prototype. Include what you say, what you observe and what you record.', null, 'Briefly explain the purpose without describing the design. Give a task, such as finding this week''s deadlines. Stay quiet and watch where they hesitate. Ask ''what are you thinking?'' Record actions, quotes, and questions, then thank them.', 'A good answer includes a short intro, a task, silent observation, neutral prompts and note-taking.', '5UX-I'),
  (5, null, 'short_answer', 'A tester says ''it''s fine'' but hesitates for a long time on one screen. How do you interpret this and follow up?', null, 'The hesitation suggests confusion despite the polite answer. Ask ''what were you thinking on this screen?'' and note which element caused it. Behavior is stronger evidence than a polite comment.', 'Mention trusting behavior and following up with an open question.', '5UX-I'),
  (5, null, 'short_answer', 'Fill in the feedback capture grid: a tester liked the layout, was confused by an icon, asked about a dark mode and suggested adding reminders.', null, 'Likes: the layout. Criticisms: the confusing icon. Questions: is there a dark mode? Ideas: add reminders.', 'Each item must go in the right quadrant.', '5UX-I'),
  (5, null, 'short_answer', 'Explain how Test connects back to Define.', null, 'Test results can show that the user need or insight was wrong or incomplete, so the team revises the POV and HMW questions and then ideates and prototypes again.', 'Mention revising the POV based on test findings.', '5UX-I'),
  (5, null, 'short_answer', 'Write a short retrospective for the Test stage: what worked, what didn''t and what you would change.', null, 'Example: What worked: testing with five students gave clear patterns. What didn''t: we explained too much so some problems were hidden. Change: write a short script and stay quiet during tasks.', 'A good retrospective is specific and shows what the team will do differently.', '3C-I'),
  (5, null, 'short_answer', 'Why does the INT100 report require peer feedback and revisions to be documented in GitHub?', null, 'To show how the work progressed and how feedback led to specific changes across stages. It makes learning visible and lets the lecturer assess progression and individual contribution.', 'Mention progression, visible change and assessment.', '3C-I');
