-- Question bank: 30 questions per stage (14 multiple choice, 10 true/false, 6 short answer).
-- Written as a migration so databases that already ran the first migration pick it up with `db push`.
-- Source: INT100 1/2026 course plan and the d.school Design Thinking Bootleg.

-- Stages are reference data that questions depend on. seed.sql no longer inserts them.
on conflict (id) do nothing;


-- Link questions to their stage's lesson where lessons already exist (no-op on a fresh database;
-- seed.sql repeats this after it inserts the lessons).
update public.questions q
   set lesson_id = (select l.id from public.lessons l where l.stage_id = q.stage_id order by l.sort_order, l.id limit 1)
 where q.lesson_id is null;
